/**
 * Icon from the cached sprite at /img/icons.svg (generated by scripts/build-icon-sprite.mjs).
 * One request for every icon on the page, and no path data in the HTML or hydration payload.
 */
export function Icon({ name, size = 20, className = "" }: { name: string; size?: number; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 256 256" fill="currentColor" aria-hidden="true" focusable="false" className={className}>
      <use href={`/img/icons.svg#${name}`} />
    </svg>
  );
}
